{
    private readonly B.QueryPinged25 _baseline = new(PongCatalog.BenchmarkId);
    private readonly K.ParallelQueryPinged25 _keryx = new(PongCatalog.BenchmarkId);
    private readonly MR.QueryPinged25 _mediatr = new(PongCatalog.BenchmarkId);
    private readonly MP.QueryPinged25 _mediatorParallel = new(PongCatalog.BenchmarkId);
    private readonly ZA.ParallelQueryPinged25 _zeroAlloc = new(PongCatalog.BenchmarkId);
    private B.QueryPinged25Publisher _baselinePublisher = null!;

    private protected override void ResolveFanOut(Subjects subjects)
    {
        _baselinePublisher = subjects.LongLived(Library.BaselineFanOut).GetRequiredService<B.QueryPinged25Publisher>();
        ZA.ZeroAllocFanOutSetup.UseStaticFactories(subjects.LongLived(Library.ZeroAllocFanOut));
    }

    [Benchmark(Baseline = true)]
    public ValueTask Baseline() => _baselinePublisher.PublishParallel(_baseline);

    [Benchmark]
    public ValueTask Keryx_Typed() => FanOutKeryxTyped.Publish(_keryx);

    [Benchmark]
    public ValueTask Keryx_Generic() => FanOutKeryxGeneric.Publish(_keryx);

    [Benchmark]
    public ValueTask MediatorSingleton_Typed() => FanOutMediatorParallelTyped.Publish(_mediatorParallel);

    [Benchmark]
    public ValueTask MediatorSingleton_Generic() => FanOutMediatorParallelGeneric.Publish(_mediatorParallel);

    [Benchmark]
    public Task MediatR_Generic() => FanOutMediatRParallel.Publish(_mediatr);

    [Benchmark]
    public ValueTask ZeroAlloc_Static() => ZAStatic.Publish(_zeroAlloc);

    [Benchmark]
    public ValueTask ZeroAlloc_IMediator() => FanOutZeroAlloc.Publish(_zeroAlloc);
}

